LogicDefinition.ScriptText:
#load "reference"
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                          //
//    Logik:           Kalte Schnittstelle Bänder                                                                       //
//                                                                                                          //
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//    Datum            Version        Autor            Beschreibung
//

//    05.09.2025       1.0.1         FG               Urversion
//
//============================================================================================================
//
//    SW-Standard      Geprüft        Prüfer           Allgemeine Informationen
//                     
//    FEE                                              Kalte Schnittstelle Bänder
//
//============================================================================================================
//
//    Beschreibung:
//    Schnittstelle von Band zu Band über Steuerungsgrenzen hinaus mit Hilfe von zwei Lichtschranken
//  
//============================================================================================================

//====================================================================================
// S I M - C O N V E Y O R   I S   S O U R C E
//====================================================================================

// Switch on SIM conveyor
if (PLC_OUT_enableToTransport && SIM_materialInSourcePresent)
{
    SIM_switchOnConvSource = true;
}

if (PLC_OUT_enableToTransport)
{
    SIM_switchOnConvSource = false;
}


// Input "is transporting"
PLC_IN_IsTransporting = SIM_switchOnConvSource;


//====================================================================================
// S I M - C O N V E Y O R   I S   D E S T I N A T I O N
//====================================================================================

// Switch on SIM conveyor
if (PLC_OUT_IsTransporting)
{
    SIM_switchOnConvDestination = true;
}

if (SIM_materialInDestinationPresent)
{
    SIM_switchOnConvSource = false;
}


// Input "enable to transport"
PLC_IN_enableToTransport = !SIM_materialInDestinationPresent;
